package com.course.platform.service.impl;

import com.course.platform.common.exception.BusinessException;
import com.course.platform.domain.entity.CoursePrivateNotification;
import com.course.platform.infra.persistence.mapper.CoursePrivateNotificationMapper;
import org.junit.jupiter.api.*;
import org.springframework.aop.framework.ProxyFactory;
import org.springframework.transaction.annotation.AnnotationTransactionAttributeSource;
import org.springframework.transaction.interceptor.TransactionInterceptor;
import java.time.Duration;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** 站内通知复用当前真实周期，阶段唯一、阅读归属及失败重试不触碰资金。 */
class CoursePrivateNotificationTransactionTest {
    CoursePrivateRenewalTransactionTest f;
    CoursePrivateNotificationMapper notices;
    CoursePrivateNotificationService service;
    @BeforeEach void setup() throws Exception {f=new CoursePrivateRenewalTransactionTest();f.setup();var config=new com.baomidou.mybatisplus.core.MybatisConfiguration();config.setMapUnderscoreToCamelCase(true);config.addMapper(CoursePrivateNotificationMapper.class);var factory=new com.baomidou.mybatisplus.extension.spring.MybatisSqlSessionFactoryBean();factory.setDataSource(f.f.f.f.jdbc.getDataSource());factory.setConfiguration(config);notices=new org.mybatis.spring.SqlSessionTemplate(factory.getObject()).getMapper(CoursePrivateNotificationMapper.class);f.f.f.table(CoursePrivateNotification.class);f.f.f.f.jdbc.execute("CREATE UNIQUE INDEX notice_once ON course_private_notification(term_id,stage)");var target=new CoursePrivateNotificationService(f.f.f.f.users,f.f.f.f.contracts,f.f.f.f.wallets,f.f.f.terms,notices,mock(CoursePrivateOperationsAccess.class),f.f.f.json,new CoursePrivateOperationsTime(f.f.f.clock));org.springframework.test.util.ReflectionTestUtils.setField(target,"enabled",true);org.springframework.test.util.ReflectionTestUtils.setField(target,"transactionManager",f.f.f.f.tx.getTransactionManager());var proxy=new ProxyFactory(target);proxy.addAdvice(new TransactionInterceptor(f.f.f.f.tx.getTransactionManager(),new AnnotationTransactionAttributeSource()));service=(CoursePrivateNotificationService)proxy.getProxy();}
    @AfterEach void clear(){f.clear();}
    int count(){return f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_notification",Integer.class);}
    @Test void repeatedAndConcurrentObservationCreatesOneActivationNotice() throws Exception {var results=f.f.f.f.concurrent(()->service.observe(f.sourceId),()->service.observe(f.sourceId));assertEquals(0,results.stream().filter(RuntimeException.class::isInstance).count());assertEquals(1,count());assertNotNull(notices.selectByStage(f.sourceId,"ACTIVATED"));service.observe(f.sourceId);assertEquals(1,count());f.f.f.f.money("100",f.f.f.wallet().getBalance());}
    @Test void remindersUseSevenThreeOneWindowsAndDoNotCatchUpSpam(){f.f.f.clock.advance(Duration.ofDays(25));service.observe(f.sourceId);assertNotNull(notices.selectByStage(f.sourceId,"EXPIRING_7"));assertNull(notices.selectByStage(f.sourceId,"EXPIRING_3"));f.f.f.clock.advance(Duration.ofDays(3));service.observe(f.sourceId);assertNotNull(notices.selectByStage(f.sourceId,"EXPIRING_3"));f.f.f.clock.advance(Duration.ofDays(1));service.observe(f.sourceId);assertNotNull(notices.selectByStage(f.sourceId,"EXPIRING_1"));int before=count();service.observe(f.sourceId);assertEquals(before,count());}
    @Test void scheduledPeriodDoesNotClaimRenewalSucceeded(){f.qualify();f.f.f.clock.advance(Duration.ofDays(24));var next=f.renew();service.observe(next.getId());assertEquals(0,count());f.f.f.clock.advance(Duration.ofDays(6));f.renew();service.observe(next.getId());assertNotNull(notices.selectByStage(next.getId(),"RENEWAL_SUCCESS"));service.observe(f.sourceId);assertNull(notices.selectByStage(f.sourceId,"EXPIRED"));}
    @Test void deliveryPublishesInboxOnceAndReadTimestampDoesNotReset(){service.observe(f.sourceId);assertEquals(1,service.deliverBatch());assertEquals(0,service.deliverBatch());var notice=notices.selectByStage(f.sourceId,"ACTIVATED");assertEquals("DELIVERED",notice.getStatus());service.markRead(7L,notice.getId());var read=notices.selectById(notice.getId()).getReadAt();f.f.f.clock.advance(Duration.ofHours(1));service.markRead(7L,notice.getId());assertEquals(read,notices.selectById(notice.getId()).getReadAt());assertThrows(BusinessException.class,()->service.markRead(8L,notice.getId()));}
    @Test void failedInboxPublicationPreservesPendingAndCanRetry(){service.observe(f.sourceId);f.f.f.f.jdbc.execute("ALTER TABLE course_private_notification ADD CONSTRAINT reject_delivery CHECK(status<>'DELIVERED')");assertEquals(0,service.deliverBatch());assertEquals("FAILED",notices.selectByStage(f.sourceId,"ACTIVATED").getStatus());assertEquals(1,notices.selectByStage(f.sourceId,"ACTIVATED").getAttempts());f.f.f.f.jdbc.execute("ALTER TABLE course_private_notification DROP CONSTRAINT reject_delivery");assertEquals(0,service.deliverBatch());f.f.f.clock.advance(Duration.ofMinutes(1));assertEquals(1,service.deliverBatch());}
    @Test void expiryNoticeUsesActualBoundaryAndCannotGrantPurchase(){f.f.f.clock.advance(Duration.ofDays(30));service.observe(f.sourceId);var row=notices.selectByStage(f.sourceId,"EXPIRED");assertNotNull(row);assertTrue(row.getPayloadJson().contains("余额保留"));assertThrows(BusinessException.class,()->f.f.buy("expired_notice"));}
    @Test void migratedLegacyFiniteTermStillGetsReminderWithoutInventedActivationNotice(){f.f.f.f.jdbc.update("UPDATE course_private_contract SET operations_mode='LEGACY_PERMANENT'");f.f.f.f.jdbc.update("UPDATE course_private_contract_term SET operations_mode='LEGACY_PERMANENT',qualification_kind='LEGACY_UNKNOWN' WHERE id=?",f.sourceId);f.f.f.clock.advance(Duration.ofDays(25));service.reconcileBatch();var row=notices.selectByStage(f.sourceId,"EXPIRING_7");assertNotNull(row);assertEquals("DELIVERED",row.getStatus());assertNull(notices.selectByStage(f.sourceId,"ACTIVATED"));assertTrue(row.getPayloadJson().contains("\"settledConsumptionAmount\":null"));}
    @Test void disabledObserverNeverCreatesOrDelivers(){org.springframework.test.util.ReflectionTestUtils.setField(service,"enabled",false);service.observe(f.sourceId);assertEquals(0,count());assertEquals(0,service.deliverBatch());}
}
